import pandas as pd
import re
from imdb import Cinemagoer
from rapidfuzz import process, fuzz

class NetflixIMDbSeriesMovieResolver:
    def __init__(self):
        self.ia = Cinemagoer()
        self.cache = {}

    def parse_netflix_title(self, title):
        title = str(title).strip()

        # Strong episodic patterns only
        patterns = [
            r'^(.+?): (?:Season|Series|Part|Vol|Book) \d+: .+$',
            r'^(.+?): Limited Series: .+$',
            r'^(.+?): (?:Episode|Chapter|Part|Vol|Section)\s*\d+.*$'
        ]

        for pattern in patterns:
            m = re.match(pattern, title, re.I)
            if m:
                return pd.Series({
                    "root": m.group(1).strip(),
                    "content_type": "series"
                })

        return pd.Series({
            "root": title,
            "content_type": "movie"
        })

    def resolve_root(self, root, content_type):
        cache_key = (root, content_type)
        if cache_key in self.cache:
            return self.cache[cache_key]

        try:
            results = self.ia.search_movie(root)
            if not results:
                result = {
                    "imdb_id": None,
                    "match_level": "not_found",
                    "confidence": 0,
                    "needs_review": True
                }
                self.cache[cache_key] = result
                return result

            if content_type == "series":
                allowed_kinds = {"tv series", "tv mini series"}
            else:
                allowed_kinds = {"movie", "tv movie"}

            filtered = [r for r in results if r.get("kind") in allowed_kinds]
            pool = filtered if filtered else results

            # Use title strings for fuzzy ranking
            candidates = [r.get("title", "") for r in pool]
            best = process.extractOne(root, candidates, scorer=fuzz.WRatio)

            if not best:
                result = {
                    "imdb_id": None,
                    "match_level": "no_match",
                    "confidence": 0,
                    "needs_review": True
                }
                self.cache[cache_key] = result
                return result

            best_title, best_score, best_idx = best
            best_obj = pool[best_idx]

            result = {
                "imdb_id": f"tt{best_obj.movieID}",
                "match_level": "root_match",
                "confidence": best_score,
                "needs_review": best_score < 90
            }
            self.cache[cache_key] = result
            return result

        except Exception as e:
            result = {
                "imdb_id": None,
                "match_level": f"error: {e}",
                "confidence": 0,
                "needs_review": True
            }
            self.cache[cache_key] = result
            return result


# Load Netflix history
df = pd.read_csv("NetflixViewingHistory_latest.csv")

# Parse rows into root + content_type
parsed = df["Title"].apply(NetflixIMDbSeriesMovieResolver().parse_netflix_title)
df = pd.concat([df, parsed], axis=1)

# Deduplicate roots
unique_roots = df[["root", "content_type"]].drop_duplicates().reset_index(drop=True)

# Resolve each unique root once
resolver = NetflixIMDbSeriesMovieResolver()
resolved_rows = []
for _, row in unique_roots.iterrows():
    resolved = resolver.resolve_root(row["root"], row["content_type"])
    resolved_rows.append({
        "root": row["root"],
        "content_type": row["content_type"],
        **resolved
    })

resolved_df = pd.DataFrame(resolved_rows)

# Map back to original rows
final_df = df.merge(resolved_df, on=["root", "content_type"], how="left")

# Save outputs
resolved_df.to_csv("Netflix_unique_roots_with_IMDb.csv", index=False)
final_df.to_csv("Netflix_history_with_series_movie_IMDb.csv", index=False)

